import sys
import os
import subprocess
import re
from datetime import datetime
import logging
from typing import List, Tuple

def evaluate_expression(expr: str) -> float:
    try:
        return eval(expr)
    except Exception as e:
        raise ValueError(f"Evaluation error: {str(e)}")

def render_line(line: str) -> str:
    pattern = re.compile(r'\{\{([^}]+)\}\}')
    parts = pattern.split(line)
    rendered_parts = []
    for part in parts:
        if part.startswith('{{') and part.endswith('}}'):
            expr = part[2:-2]
            try:
                value = evaluate_expression(expr)
                if isinstance(value, int):
                    rendered_parts.append(str(value))
                else:
                    rendered_parts.append(str(value))
            except ValueError as e:
                raise ValueError(f"Placeholder error: {e}")
        else:
            rendered_parts.append(part)
    return ''.join(rendered_parts)

def process_template(template_path: str) -> int:
    try:
        with open(template_path, 'r') as file:
            lines = file.readlines()
    except IOError:
        print(f"Error: Could not open template file {template_path}", file=sys.stderr)
        return 3

    log_file = open('run.log', 'w')
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        try:
            rendered_line = render_line(stripped_line)
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_file.write(f"{timestamp}\t{rendered_line}\t0\t\n\t\n")
            result = subprocess.run(rendered_line, shell=True, text=True, capture_output=True)
            exit_code = result.returncode
            stdout = result.stdout.replace('\n', '\\n')
            stderr = result.stderr.replace('\n', '\\n')
            log_file.write(f"{timestamp}\t{rendered_line}\t{exit_code}\t{stdout}\t{stderr}\n")
            if exit_code != 0:
                return 1
        except ValueError as e:
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_file.write(f"{timestamp}\t{line.strip()}\tEVAL_ERROR\t{str(e).replace('\t', ' ')}\n")
            return 2
    log_file.close()
    return 0

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python render_and_run.py <template_file>", file=sys.stderr)
        sys.exit(1)
    sys.exit(process_template(sys.argv[1]))

import sys
import os
import subprocess
import re
from datetime import datetime
import shlex

def evaluate_expression(expr):
    try:
        result = eval(expr, {'__builtins__': None}, {})
        if isinstance(result, float):
            return f"{result:.10f}".rstrip('0').rstrip('.') if '.' in f"{result:.10f}" else str(result)
        return str(result)
    except Exception as e:
        raise ValueError(str(e))

def render_command(line):
    placeholders = re.findall(r'\{\{([^}]+)\}\}', line)
    for placeholder in placeholders:
        try:
            value = evaluate_expression(placeholder)
            line = line.replace(f'{{{{{placeholder}}}}}', value)
        except ValueError as e:
            raise ValueError(f"Error evaluating placeholder '{placeholder}': {e}")
    return line

def main():
    if len(sys.argv) != 2:
        print("Usage: python render_and_run.py <template_file>", file=sys.stderr)
        sys.exit(3)

    template_file = sys.argv[1]
    if not os.path.exists(template_file):
        print(f"Error: Template file '{template_file}' does not exist.", file=sys.stderr)
        sys.exit(3)

    with open(template_file, 'r') as f:
        lines = f.readlines()

    run_log = open('run.log', 'w')
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        try:
            rendered_cmd = render_command(stripped_line)
            cmd_parts = shlex.split(rendered_cmd)
            result = subprocess.run(cmd_parts, capture_output=True, text=True, check=True)
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_entry = f"{timestamp}\t{rendered_cmd}\t{result.returncode}\t{result.stdout}\t{result.stderr}\n"
            run_log.write(log_entry)
        except subprocess.CalledProcessError as e:
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_entry = f"{timestamp}\t{stripped_line}\tEVAL_ERROR\t{e}\n"
            print(log_entry.replace('\t', ' '), file=sys.stderr)
            sys.exit(2)
        except ValueError as e:
            timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
            log_entry = f"{timestamp}\t{stripped_line}\tEVAL_ERROR\t{e}\n"
            print(log_entry.replace('\t', ' '), file=sys.stderr)
            sys.exit(2)

    run_log.close()
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import os
import subprocess
import re
from datetime import datetime, timezone
from typing import List, Tuple

def evaluate_expression(expr: str) -> float:
    try:
        return eval(expr)
    except Exception as e:
        raise ValueError(f"Evaluation error: {str(e)}")

def render_command(line: str) -> str:
    def replace_placeholder(match):
        expr = match.group(1)
        try:
            result = evaluate_expression(expr)
            if isinstance(result, int):
                return str(result)
            else:
                return f"{result:.10f}".rstrip('0').rstrip('.') if '.' in f"{result:.10f}" else str(result)
        except ValueError as e:
            raise ValueError(f"Placeholder evaluation failed: {str(e)}")

    pattern = re.compile(r'\{\{\s*([^}]+)\s*\}\}')
    return pattern.sub(replace_placeholder, line)

def process_template(template_path: str) -> int:
    try:
        with open(template_path, 'r') as file:
            lines = file.readlines()
    except IOError:
        print(f"Error: Could not open template file {template_path}", file=sys.stderr)
        return 3

    log_file = open('run.log', 'w')
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith('#'):
            continue

        try:
            rendered_line = render_command(stripped_line)
        except ValueError as e:
            timestamp = datetime.now(timezone.utc).isoformat() + 'Z'
            log_file.write(f"{timestamp}\t{stripped_line}\tEVAL_ERROR\t{str(e).replace('\t', ' ')}\n")
            return 2

        try:
            result = subprocess.run(
                rendered_line,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=True
            )
        except subprocess.CalledProcessError as e:
            timestamp = datetime.now(timezone.utc).isoformat() + 'Z'
            log_file.write(f"{timestamp}\t{rendered_line}\t{e.returncode}\t\n\n\n\n\n")
            return e.returncode

        timestamp = datetime.now(timezone.utc).isoformat() + 'Z'
        log_file.write(f"{timestamp}\t{rendered_line}\t{result.returncode}\t{result.stdout.replace('\n', '\\n')}\t{result.stderr.replace('\n', '\\n')}\n")

    log_file.close()
    return 0

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python render_and_run.py <template_file>", file=sys.stderr)
        sys.exit(1)

    sys.exit(process_template(sys.argv[1]))
